use super::*;
use std::{fs,io::{Read,Write},net::TcpListener,path::PathBuf,sync::{Arc,atomic::{AtomicBool,AtomicU64,Ordering}},thread,time::{Duration,SystemTime,UNIX_EPOCH}};
use zeroize::Zeroizing;
fn temp()->PathBuf{static N:AtomicU64=AtomicU64::new(0);let p=std::env::temp_dir().join(format!("cancel-no-http-{}-{}-{}",std::process::id(),SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos(),N.fetch_add(1,Ordering::SeqCst)));fs::create_dir(&p).unwrap();p}
fn scope()->Scope{Scope{tournament_id:"11111111-1111-4111-8111-111111111111".into(),tournament_slug:"cup".into(),exchanges:[("101".into(),"201".into())].into()}}
fn spec()->RequestSpec{RequestSpec{method:"DELETE".into(),endpoint:"/orders/991".into(),body:None,body_json:None}}
fn permit(expiry:u64)->Permit{Permit{run_id:"fixture".into(),intent_id:"q1-cancel".into(),owner:"Codex".into(),expires_at_ms:expiry,maximum_quantity:10,maximum_cost:"4.000000".into()}}
struct C{now:Arc<AtomicU64>,sleep_fails:bool}
impl Clock for C{fn now_ms(&self)->u64{self.now.load(Ordering::SeqCst)}fn sleep_ms(&mut self,n:u64)->Result<()>{if self.sleep_fails{return Err(fail("FIXTURE_WAIT_FAILED"))}self.now.fetch_add(n,Ordering::SeqCst);Ok(())}}
struct A{owner:Arc<AtomicBool>,clock:Arc<AtomicU64>,network_calls:AtomicU64,deny_network:u64,regress_on_deny:bool,deny_all:bool}
impl Authority for A{
 fn can_read(&self,_:&Scope)->bool{self.owner.load(Ordering::SeqCst)}
 fn owns_order(&self,id:&str)->bool{self.owner.load(Ordering::SeqCst)&&id=="991"}
 fn authorize(&self,_:&Scope,_:&RequestSpec,_:&Permit,network:bool,_:u64)->Result<()>{if network&&self.network_calls.fetch_add(1,Ordering::SeqCst)+1==self.deny_network{if self.regress_on_deny{self.clock.store(999,Ordering::SeqCst);}return Err(fail("FIXTURE_DENIED"))}need(!self.deny_all,"FIXTURE_DENIED")}
}
struct K{mode:u8,clock:Arc<AtomicU64>}
impl CredentialProvider for K{fn load(&self)->Result<Zeroizing<String>>{match self.mode{1=>Err(fail("FIXTURE_CREDENTIAL_UNAVAILABLE")),2=>Ok(Zeroizing::new("invalid\nheader".into())),3=>{self.clock.store(999,Ordering::SeqCst);Ok(Zeroizing::new("OFFLINE_FIXTURE_ONLY".into()))},_=>Ok(Zeroizing::new("OFFLINE_FIXTURE_ONLY".into()))}}}
struct Server{base:String,count:Arc<AtomicU64>,alive:Arc<AtomicBool>,join:Option<thread::JoinHandle<()>>}
impl Server{
 fn new(status:u16,data:Value)->Self{let socket=TcpListener::bind("127.0.0.1:0").unwrap();socket.set_nonblocking(true).unwrap();let base=format!("http://{}/api/v1",socket.local_addr().unwrap());let count=Arc::new(AtomicU64::new(0));let counter=count.clone();let alive=Arc::new(AtomicBool::new(true));let run=alive.clone();let bytes=data.to_string();let join=thread::spawn(move||{while run.load(Ordering::SeqCst){let(mut stream,_)=match socket.accept(){Ok(v)=>v,Err(e)if e.kind()==std::io::ErrorKind::WouldBlock=>{thread::sleep(Duration::from_millis(1));continue},Err(_)=>break};stream.set_read_timeout(Some(Duration::from_secs(2))).unwrap();let mut raw=Vec::new();let mut buf=[0u8;1024];while !raw.windows(4).any(|w|w==b"\r\n\r\n"){let n=stream.read(&mut buf).unwrap_or(0);if n==0{break}raw.extend_from_slice(&buf[..n]);}if !raw.is_empty(){counter.fetch_add(1,Ordering::SeqCst);let reply=format!("HTTP/1.1 {status} Fixture\r\nContent-Type: application/json\r\nConnection: close\r\nContent-Length: {}\r\n\r\n{bytes}",bytes.len());let _=stream.write_all(reply.as_bytes());}}});Self{base,count,alive,join:Some(join)}}
 fn count(&self)->u64{self.count.load(Ordering::SeqCst)}
}
impl Drop for Server{fn drop(&mut self){self.alive.store(false,Ordering::SeqCst);if let Some(j)=self.join.take(){j.join().unwrap();}}}
struct F{p:PathBuf,t:Transport,now:Arc<AtomicU64>,owner:Arc<AtomicBool>,server:Server}
impl F{
 fn new(deny:u64,credential:u8,sleep_fails:bool,regress:bool)->Self{Self::response(deny,credential,sleep_fails,regress,200,json!({"orderId":991,"tournamentId":scope().tournament_id,"balance":100,"availableAdvance":0,"buyingPower":100}))}
 fn response(deny:u64,credential:u8,sleep_fails:bool,regress:bool,status:u16,data:Value)->Self{let p=temp();let server=Server::new(status,data);let now=Arc::new(AtomicU64::new(1000));let owner=Arc::new(AtomicBool::new(true));let mut t=Transport::new_for_mock(Config{queue_dir:p.clone(),account_scope:"fixture-account".into(),scope:scope(),maximum_pages:3,writes_enabled:true},Box::new(K{mode:credential,clock:now.clone()}),Box::new(C{now:now.clone(),sleep_fails}),Box::new(A{owner:owner.clone(),clock:now.clone(),network_calls:AtomicU64::new(0),deny_network:deny,regress_on_deny:regress,deny_all:false}),server.base.clone()).unwrap();t.admission_state().unwrap();Self{p,t,now,owner,server}}
 fn fail(&mut self,expiry:u64)->TransportError{self.t.cancel("991".into(),permit(expiry)).err().expect("actual original failure")}
}
impl Drop for F{fn drop(&mut self){let _=fs::remove_dir_all(&self.p);}}

#[test]fn actual_expired_initial_guard_mints_owned_bound_single_use_proof_without_http(){let mut f=F::new(0,0,false,false);let p=permit(1000);let e=f.fail(1000);assert_eq!(e.code,"PERMIT_EXPIRED_OR_INVALID");let proof=f.t.take_cancel_no_http_proof().unwrap();proof.validate_binding(&spec(),&p,999,&e).unwrap();assert_eq!(proof.evidence()["kind"],"owned_delete_before_admit_no_http_v1");assert_eq!(proof.evidence()["callStartedAtMs"],1000);assert_eq!(proof.evidence()["source"]["captureCutoffExclusiveMs"],1001);assert_eq!(proof.evidence()["source"]["verifiedHead"]["lastClock"],1000);assert_eq!(proof.evidence()["retryPermitted"],false);assert_eq!(proof.evidence()["orderTerminal"],false);assert!(f.t.take_cancel_no_http_proof().is_err());assert_eq!(f.server.count(),0);}
#[test]fn actual_admit_wait_expiry_uses_current_end_not_fake_original_attempt_watermark(){let mut f=F::new(0,0,false,false);f.t.request(Endpoint::Account).unwrap();assert_eq!(f.server.count(),1);let e=f.fail(1100);assert_eq!(e.code,"PERMIT_EXPIRED_OR_INVALID");let proof=f.t.take_cancel_no_http_proof().unwrap();proof.validate_binding(&spec(),&permit(1100),1000,&e).unwrap();assert!(proof.evidence()["callEndedAtMs"].as_u64().unwrap()>1000);assert_eq!(proof.evidence()["source"]["verifiedHead"]["binding"]["intent"],"fixture:q1-cancel");assert_eq!(f.server.count(),1);}
#[test]fn actual_wait_clock_failure_is_no_http_only_with_healthy_unchanged_core(){let mut f=F::new(0,0,true,false);f.t.request(Endpoint::Account).unwrap();let e=f.fail(5000);assert_eq!(e.code,"FIXTURE_WAIT_FAILED");let proof=f.t.take_cancel_no_http_proof().unwrap();proof.validate_binding(&spec(),&permit(5000),1000,&e).unwrap();assert_eq!(proof.evidence()["source"]["verifiedHead"]["lastClock"],1000);assert_eq!(proof.evidence()["source"]["captureCutoffExclusiveMs"],1001);assert_eq!(f.server.count(),1);}
#[test]fn actual_admitted_network_guard_or_credentials_complete_durably_not_sent(){for(deny,credential)in [(1,0),(0,1),(0,2)]{let mut f=F::new(deny,credential,false,false);let e=f.fail(5000);assert!(!e.may_have_executed);let proof=f.t.take_cancel_no_http_proof().unwrap();proof.validate_binding(&spec(),&permit(5000),1000,&e).unwrap();assert_eq!(proof.evidence()["kind"],"owned_delete_durable_not_sent_v1");assert_eq!(proof.evidence()["source"]["beforeRecord"]["state"]["active"]["network_started"],false);assert_eq!(proof.evidence()["source"]["completionRecord"]["state"]["active"],Value::Null);assert_eq!(f.server.count(),0);}}
#[test]fn post_marker_guard_failure_never_mints_even_with_zero_actual_http(){let mut f=F::new(2,0,false,false);let e=f.fail(5000);assert!(e.may_have_executed);assert!(f.t.take_cancel_no_http_proof().is_err());assert!(f.t.queue.summary().unwrap().has_unknown);assert_eq!(f.server.count(),0);}
#[test]fn attempted_network_marker_command_failure_never_mints(){let mut f=F::new(0,3,false,false);let e=f.fail(5000);assert_eq!(e.code,"CLOCK_REGRESSION");assert!(f.t.take_cancel_no_http_proof().is_err());assert!(f.t.queue.summary().unwrap().state.manual_review);assert_eq!(f.server.count(),0);}
#[test]fn durable_completion_failure_preserves_poison_without_proof(){let mut f=F::new(1,0,false,true);let e=f.fail(5000);assert_eq!(e.code,"LOCAL_NOT_SENT_DURABILITY_UNCERTAIN");assert!(f.t.poisoned);assert!(f.t.take_cancel_no_http_proof().is_err());assert_eq!(f.server.count(),0);}
#[test]fn every_actual_http_response_is_not_no_http_even_known_rejection(){for status in [200,400,500]{let mut f=F::response(0,0,false,false,status,json!({"orderId":991,"tournamentId":scope().tournament_id}));let _=f.t.cancel("991".into(),permit(5000));assert!(f.t.take_cancel_no_http_proof().is_err());assert_eq!(f.server.count(),1);}}
#[test]fn exact_original_spec_permit_external_clock_and_error_cannot_be_rebound(){let mut f=F::new(0,0,false,false);let e=f.fail(1000);let proof=f.t.take_cancel_no_http_proof().unwrap();for n in 0..7{let mut s=spec();let mut p=permit(1000);let mut error=e.clone();let mut at=1000;match n{0=>s.endpoint="/orders/992".into(),1=>s.method="POST".into(),2=>s.body=Some(json!({})),3=>p.intent_id="other".into(),4=>error.may_have_executed=true,5=>at=1001,_=>p.expires_at_ms=999}assert!(proof.validate_binding(&s,&p,at,&error).is_err(),"{n}");}assert_eq!(f.server.count(),0);}
#[test]fn intervening_invalid_sdk_calls_reads_status_compaction_and_head_changes_invalidate(){for mode in 0..8{let mut f=F::new(0,0,false,false);f.fail(1000);match mode{0=>{assert!(f.t.request(Endpoint::OrderBook{market_id:"999".into(),depth:20}).is_err());},1=>{f.t.admission_state().unwrap();},2=>{f.t.compact().unwrap();},3=>{f.t.admission_summary().unwrap();},4=>{f.t.package_queue_quiet().unwrap();},5=>{f.t.queue.command(json!({"op":"status","scope":"fixture-account","now":1000})).unwrap();},6=>{assert!(f.t.cancel("0".into(),permit(1000)).is_err());},_=>{assert!(f.t.take_local_not_sent_proof().is_err());}}assert!(f.t.take_cancel_no_http_proof().is_err(),"{mode}");assert_eq!(f.server.count(),0);}}
#[test]fn ownership_poison_lease_clock_or_original_queue_source_changes_deny_consumption(){for mode in 0..5{let mut f=F::new(0,0,false,false);f.fail(1000);match mode{0=>f.owner.store(false,Ordering::SeqCst),1=>f.t.poisoned=true,2=>fs::write(f.p.join("offline-account-queue.lock"),b"different-owner").unwrap(),3=>f.now.store(999,Ordering::SeqCst),_=>{let path=f.p.join("account-queue.jsonl");let mut bytes=fs::read(&path).unwrap();bytes.pop();fs::write(path,bytes).unwrap();}}assert!(f.t.take_cancel_no_http_proof().is_err(),"{mode}");assert_eq!(f.server.count(),0);}}
#[test]fn unrelated_global_unknown_blocks_initial_expiry_proof_despite_exact_cancel_absence(){let mut f=F::new(0,0,false,false);let b=json!({"intent":"other","key":"other-key","payload_hash":"a".repeat(64)});for op in ["admit","network"]{f.t.queue.command(json!({"op":op,"scope":"fixture-account","now":1000,"request":"other","write":true,"binding":b,"authorized":true,"lease_valid":true,"permit_valid":true})).unwrap();}f.t.queue.command(json!({"op":"complete","scope":"fixture-account","now":1000,"request":"other","outcome":"unknown"})).unwrap();f.fail(1000);assert!(f.t.take_cancel_no_http_proof().is_err());assert!(f.t.queue.summary().unwrap().has_unknown);assert_eq!(f.server.count(),0);}
#[test]fn prior_cancel_binding_is_not_erased_or_converted_into_retry_permission(){let mut f=F::new(1,0,false,false);f.fail(5000);let p=f.t.take_cancel_no_http_proof().unwrap();assert_eq!(p.evidence()["retryPermitted"],false);let binding=cancel_not_sent::binding(&scope(),&spec(),&permit(5000)).unwrap();assert!(f.t.queue.lookup_intent(&binding.intent).unwrap().binding.is_some());f.fail(1000);assert!(f.t.take_cancel_no_http_proof().is_err());assert!(f.t.queue.lookup_intent(&binding.intent).unwrap().binding.is_some());assert_eq!(f.server.count(),0);}
#[test]fn no_first_call_proof_for_unowned_order_or_arbitrary_authority_failure(){let mut f=F::new(0,0,false,false);assert!(f.t.cancel("992".into(),permit(1000)).is_err());assert!(f.t.take_cancel_no_http_proof().is_err());f.t.authority=Box::new(A{owner:f.owner.clone(),clock:f.now.clone(),network_calls:AtomicU64::new(0),deny_network:0,regress_on_deny:false,deny_all:true});f.fail(5000);assert!(f.t.take_cancel_no_http_proof().is_err());assert_eq!(f.server.count(),0);}
